// stand in the open next to a patrolling bot: it must spot and shoot us
const engaged = await page.evaluate(async () => {
  GAME.test.start('vector');
  GAME.test.skipBuy();
  await new Promise(r => setTimeout(r, 200));
  for (let i = 0; i < 24; i++) { // up to ~6s, re-park near bot 0
    const b = GAME.test.botInfo()[0];
    GAME.test.pose(b.pos[0] + 3, 0, b.pos[2] + 3, 0, 0);
    await new Promise(r => setTimeout(r, 250));
    if (GAME.test.state().hp < 100) return { hp: GAME.test.state().hp, ms: (i + 1) * 250 };
  }
  return { hp: 100, ms: 6000 };
});
check('bot AI spots and engages exposed player', engaged.hp < 100, `hp ${engaged.hp} after ${engaged.ms}ms`);

